local VERSION='9.0.0'
local readiness, kits, recovery = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('CalculateUnitReadinessV9',function(unit)local data=type(unit)=='table'and unit or{};local score=100-(tonumber(data.maintenanceDue)or 0)*20-(tonumber(data.missingItems)or 0)*8-(tonumber(data.crewFatigue)or 0)*.35-(tonumber(data.fuelDeficit)or 0)*.25;score=math.max(0,math.min(100,math.floor(score)));local item={unit=data.id or'unknown',score=score,status=score>=85 and'ready'or score>=60 and'limited'or'out_of_service',createdAt=os.time()};readiness[item.unit]=item;return item end)
exports('ReserveCriticalCareKitV9',function(unit,callId,contents)local item={id=uid('KIT'),unit=unit,callId=callId,contents=contents or{},status='reserved',createdAt=os.time()};kits[item.id]=item;return item.id,item end)
exports('CreateFleetRecoveryPlanV9',function(units)local item={id=uid('FLEET'),actions={},createdAt=os.time()};for _,u in ipairs(type(units)=='table'and units or{})do local r=exports['dpn-medical-ambulance']:CalculateUnitReadinessV9(u);if r.score<60 then item.actions[#item.actions+1]={unit=r.unit,action='remove_and_service'}elseif r.score<85 then item.actions[#item.actions+1]={unit=r.unit,action='restock_or_relieve_crew'}end end;recovery[item.id]=item;return item end)
exports('GetV9AmbulanceBoard',function()return{version=VERSION,readiness=readiness,kits=kits,recovery=recovery,generatedAt=os.time()}end)
CreateThread(function()Wait(6000);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-ambulance',VERSION,{'unit_readiness','critical_care_kits','fleet_recovery','equipment_resilience'})end);print('[dpn-medical-ambulance] v9 fleet readiness and critical-care kit orchestration active')end)
